fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since the problem guarantees a.len() == b.len(), we can zip them directly.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| (x as i32) > (y as i32))
     .collect()
}

